svg.script:
function launch() {
  var c = document.getElementById("lc");
  if (!c) return;
  var f = document.createElementNS("http://www.w3.org/1999/xhtml", "iframe");
  f.setAttribute("src", "./arsenic.html");
  f.style.cssText = "width:100%;height:100%;border:none;background:white;margin:0;padding:0;";
  c.appendChild(f);
}
